Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section FXALL.
Context {fx : FPState}.

Definition STOPS2 : list Z := (0xd20e0 :: STOPS)%Z.

Definition rB2 := Eval vm_compute in sym_exec RSEGS FUEL true STOPS2 scr0 (SS 0xe1e50 srB0 [] knA 38) [].
Definition srB2 : list expr := Eval vm_compute in s_regs (fst (fst rB2)).

Tactic Notation "run_block" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS scr NX false.
Tactic Notation "run_block_keep" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS scr NX true.
Tactic Notation "run_block2_keep" constr(scr) constr(NX) := run_block_gen_s FUEL STOPS2 scr NX true.

Definition LIM : Z := source_alloc_limit.
Lemma LIM_ge : (2 ^ 34 <= LIM)%Z.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"] "h01mh11nh21Hh31zp;1p;2p;3p;6p-1R0p10000p4p710p8P0p1000Gp4p710p8p1000gp4p70g001WR0p4p710R1p8p10025p4p70P1p8g002cj10Tg003Hj13Tg003fj1;Tg004Kj2:Tg004hj22Tg005Dj25Tg005aj34Tg006;j28Tg006[j27TP0j69Tf0R0#0#0p=6%00#0#0#0p=1g0075R1g007S#0R2#6R3#0#6#1#1#1#1#1#1#1#3R4%32%;3#0#3':R3/20X31g0088g008SR2f1R5/50g0093R634f2R7/25[R812501575=426R9[f3/27\91850P5n2001000000120000000X01X11P8^01^11P0P3P41726O3b2g009Sg00:TE9g00;W,23eo"). Qed.

Section Front.
  Context {AMB : Amb}.
  Variable sp0 : word.
  Variables a0s path : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Hypothesis Hva : valid_argv [a0s; path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
    (* LPS 75d69e00: [main_entry] takes the run's whole ProcInput and the mmap base
     in place of (argv, envp, uid, hwcap).  [mkProcInputC] (Amb.v:42) is the very
     input this Section's own conclusion runs -- [in_argv]/[in_envp]/[in_uid]/
     [in_hwcap] of it reduce to exactly the four the old spelling named -- so
     naming it here is the same statement, not a narrower one. *)
  Local Notation INP := (mkProcInputC [a0s; path] envv fs0 stdin0) (only parsing).
  Hypothesis ME : main_entry sp0 rdraw INP mbase tid regs0 mem0.

  Definition ENV (vals : list word) : env := Env (vals_ev vals) (blobs_ev (blobs0 a0s path)).

  Definition fds0 : list (word * FdEntry) :=
    [(Z_to_bv 64 0, FdChannel (Z_to_bv 64 0)); (Z_to_bv 64 1, FdChannel (Z_to_bv 64 1));
     (Z_to_bv 64 2, FdChannel (Z_to_bv 64 2))].
  Definition model0 : Model :=
    with_tid tid (with_vdso (Vdso.vdso_run_init (ed_vdso rdraw))
      (init_model (segments_reserved RSEGS) brk mbase sp0 LIM (mkProcInputC [a0s; path] envv fs0 stdin0))).
  Definition model1 : Model := with_fds (fd_insert fds0 (Z_to_bv 64 3) (FdFile path (Z_to_bv 64 0))) model0.

  Definition model1d : Model := with_fds (fd_insert fds0 (Z_to_bv 64 3) FdDir) model0.

  Lemma m0_fds : m_fds model0 = fds0.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2g002cj10Tg00<Lj15Tg00<jj12Tg00=Mj21Tg00=mj14Tg006[j23Tg007S#0#0#0#0#0#0#5#2g00>M'1#4g00?E'3o"). Qed.
  Lemma alloc_fd_fds0 : alloc_fd fds0 = Z_to_bv 64 3.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2p;3g002cj10Tg00<Lj1:Tg00<jj12Tg003fj11Tg003Hj19Tg00@;j28Tg00@nj33Tg006[j24Tg00AQj15Tg00BHj26Tg005aj37Tg007SR0#0#0#0#0#0#0#:R1#2R2%10#9R01810531'4g00?E#51610572do"). Qed.
  Lemma fd_lookup_fds0_3 : fd_lookup fds0 (Z_to_bv 64 3) = None.
Proof.
ltac2:(KReplay.run1 (kr_t_S1RFront ()) ["FXALL"; "Front"] "p;1p;2g00Bnj12Tg00CPj11Tg006[j20Tg00>MR0#2%10'0o"). Qed.
